Effect.fn(function* ({ before, after }) {
      if (before._tag !== "Open" || after._tag !== "Open") return true;
      if (before.customerId === after.customerId) return true;
      return (yield* CurrentActor)._tag === "Agent";
    })

Bank.TransfersLoseNoMoney.source:
(bank) => {
      const events = bank.Account.flatMap((account) => account.events);
      const sum = (amounts: ReadonlyArray<number>) =>
        amounts.reduce((total, amount) => total + amount, 0);
      const taken = sum(
        events.flatMap((event) => (event._tag === "TransferDebited" ? [event.amount] : [])),
      );
      const given = sum(
        events.flatMap((event) =>
          event._tag === "TransferCredited" ||
          event._tag === "TransferRefunded" ||
          event._tag === "RefundStranded"
            ? [event.amount]
            : [],
        ),
      );
      return taken === given;
    }

